        return switch (self) {
            .ring => "Ring",
            .tree => "Tree",
            .collnet_direct => "CollNetDirect",
            .collnet_chain => "CollNetChain",
        };
    }

    pub fn count() usize {
        return 4;
    }

    pub fn fromIndex(idx: usize) Algorithm {
        return switch (idx) {
            0 => .ring,
            1 => .tree,
            2 => .collnet_direct,
            3 => .collnet_chain,
            else => .ring,
        };
    }
};

