pub const ContentionModel = struct {
    hw: HardwareSpec,
    sm_contention_alpha: f64,
    global_contention_beta: f64,
    cache_contention_gamma: f64,

    pub fn init(hw: HardwareSpec) ContentionModel {
        var alpha: f64 = 1.0;
        var beta: f64 = 1.0;
        if (hw.nvlink_available) {
            alpha = 1.2;
            beta = 1.5;
        } else {
            alpha = 0.8;
            beta = 1.0;
        }
        return ContentionModel{
            .hw = hw,
            .sm_contention_alpha = alpha,
            .global_contention_beta = beta,
            .cache_contention_gamma = 0.1,
        };
    }

    pub fn computeSMOccupancy(self: *const ContentionModel, nc: u32) f64 {
        const nc_f: f64 = @floatFromInt(nc);
        const total_sms_f: f64 = @floatFromInt(self.hw.total_sms);
        const occupancy = self.sm_contention_alpha * nc_f / total_sms_f;
        return @min(occupancy, 0.95);
    }

    pub fn computeGlobalResourceContention(self: *const ContentionModel, nc: u32, chunk_size: u32) f64 {
        const nc_f: f64 = @floatFromInt(nc);
        const chunk_f: f64 = @floatFromInt(chunk_size);
        const chunk_max_f: f64 = @floatFromInt(CHUNK_MAX);
        const normalized_chunk = chunk_f / chunk_max_f;
        const contention_factor = self.global_contention_beta * nc_f * normalized_chunk;
        const max_contention = 0.9 * self.hw.peak_memory_bandwidth;
        return @min(contention_factor * self.hw.peak_memory_bandwidth / @as(f64, @floatFromInt(self.hw.total_sms)), max_contention);
    }

    pub fn computeEffectiveBandwidth(self: *const ContentionModel, nc: u32, chunk_size: u32) f64 {
        const v = self.computeGlobalResourceContention(nc, chunk_size);
        const effective = self.hw.peak_memory_bandwidth - v;
        return @max(effective, self.hw.peak_memory_bandwidth * 0.05);
    }

    pub fn computeWaveCount(self: *const ContentionModel, comp: CompOperator, nc: u32) f64 {
        const total_sms_f: f64 = @floatFromInt(self.hw.total_sms);
        const nc_f: f64 = @floatFromInt(nc);
        const available_sms = total_sms_f - self.sm_contention_alpha * nc_f;
        const clamped_sms = @max(available_sms, 1.0);
        const tb_per_sm: f64 = @floatFromInt(comp.thread_blocks);
        const total_tb: f64 = @floatFromInt(comp.total_thread_blocks);
        const capacity = clamped_sms * tb_per_sm;
        if (capacity <= 0.0) return total_tb;
        return @ceil(total_tb / capacity);
    }

    pub fn computePerWaveLatency(self: *const ContentionModel, comp: CompOperator, nc: u32, chunk_size: u32) f64 {
        const nc_f: f64 = @floatFromInt(nc);
        const total_sms_f: f64 = @floatFromInt(self.hw.total_sms);
        const sm_fraction = 1.0 - nc_f / total_sms_f;
        const clamped_fraction = @max(sm_fraction, 0.05);
        const effective_bw = self.computeEffectiveBandwidth(nc, chunk_size);
        const tb_f: f64 = @floatFromInt(comp.thread_blocks);
        const data_transfer_time = clamped_fraction * tb_f * comp.data_size_per_tb / effective_bw;
        return comp.base_latency + data_transfer_time;
    }

    pub fn computeCompTime(self: *const ContentionModel, comp: CompOperator, nc: u32, chunk_size: u32) f64 {
        const theta = self.computeWaveCount(comp, nc);
        const f = self.computePerWaveLatency(comp, nc, chunk_size);
        return theta * f;
    }

    pub fn computeTotalCompTime(self: *const ContentionModel, comps: []const CompOperator, comms: []const CommOperator) f64 {
        var total: f64 = 0.0;
        for (comps) |comp| {
            var max_nc: u32 = 0;
            var max_chunk: u32 = 0;
            for (comms) |comm| {
                if (comm.config.num_channels > max_nc) max_nc = comm.config.num_channels;
                if (comm.config.chunk_size > max_chunk) max_chunk = comm.config.chunk_size;
            }
            if (max_nc == 0) max_nc = NC_MIN;
            if (max_chunk == 0) max_chunk = CHUNK_MIN;
            total += self.computeCompTime(comp, max_nc, max_chunk);
        }
        return total;
    }

    pub fn estimateCommTime(self: *const ContentionModel, comm: *const CommOperator) f64 {
        _ = self;
        const msg_f: f64 = @floatFromInt(comm.message_size);
        const nc_f: f64 = @floatFromInt(comm.config.num_channels);
        const chunk_f: f64 = @floatFromInt(comm.config.chunk_size);
        const nt_f: f64 = @floatFromInt(comm.config.num_threads);
        const base_latency: f64 = 5.0e-6;
        const per_channel_throughput = chunk_f * nt_f / 256.0;
        const effective_throughput = nc_f * per_channel_throughput;
        if (effective_throughput <= 0.0) return math.inf(f64);
        const transfer_time = msg_f / effective_throughput;
        var algo_factor: f64 = 1.0;
        switch (comm.config.algorithm) {
            .ring => algo_factor = 1.0,
            .tree => algo_factor = 0.85,
            .collnet_direct => algo_factor = 0.75,
            .collnet_chain => algo_factor = 0.80,
        }
        var proto_factor: f64 = 1.0;
        switch (comm.config.protocol) {
            .ll => proto_factor = 1.2,
            .ll128 => proto_factor = 1.0,
            .simple => proto_factor = 0.9,
        }
        return (base_latency + transfer_time) * algo_factor * proto_factor;
    }
};

