pub const NC_MIN: u32 = 1;
pub const NC_MAX: u32 = 64;
pub const NT_MIN: u32 = 64;
pub const NT_MAX: u32 = 1024;
pub const CHUNK_MIN: u32 = 1024;
pub const CHUNK_MAX: u32 = 4 * 1024 * 1024;
pub const DEFAULT_NC: u32 = 8;
pub const DEFAULT_NT: u32 = 256;
pub const DEFAULT_CHUNK: u32 = 2 * 1024 * 1024;
pub const PROFILE_WARMUP_ITERS: u32 = 5;
pub const PROFILE_MEASURE_ITERS: u32 = 10;
pub const MAX_TUNING_ITERATIONS: u32 = 512;
pub const CONVERGENCE_THRESHOLD: f64 = 0.005;
pub const LEARNING_RATE_BASE: f64 = 1.0;
pub const LEARNING_RATE_DECAY: f64 = 0.9;

pub const CommConfig = struct {
    algorithm: Algorithm,
    protocol: Protocol,
    transport: Transport,
    num_channels: u32,
    num_threads: u32,
    chunk_size: u32,

    pub fn init(algo: Algorithm, proto: Protocol, trans: Transport, nc: u32, nt: u32, c: u32) CommConfig {
        return CommConfig{
            .algorithm = algo,
            .protocol = proto,
            .transport = trans,
            .num_channels = clampNC(nc),
            .num_threads = clampNT(nt),
            .chunk_size = clampChunk(c),
        };
    }

    pub fn initDefault() CommConfig {
        return CommConfig{
            .algorithm = .ring,
            .protocol = .simple,
            .transport = .p2p,
            .num_channels = DEFAULT_NC,
            .num_threads = DEFAULT_NT,
            .chunk_size = DEFAULT_CHUNK,
        };
    }

    pub fn initMinimal() CommConfig {
        return CommConfig{
            .algorithm = .ring,
            .protocol = .simple,
            .transport = .p2p,
            .num_channels = NC_MIN,
            .num_threads = NT_MIN,
            .chunk_size = CHUNK_MIN,
        };
    }

    pub fn clampNC(nc: u32) u32 {
        if (nc < NC_MIN) return NC_MIN;
        if (nc > NC_MAX) return NC_MAX;
        return nc;
    }

    pub fn clampNT(nt: u32) u32 {
        if (nt < NT_MIN) return NT_MIN;
        if (nt > NT_MAX) return NT_MAX;
        var v = nt;
        if (v & (v - 1) != 0) {
            var p: u32 = NT_MIN;
            while (p < v and p <= NT_MAX) {
                p *= 2;
            }
            v = if (p <= NT_MAX) p else NT_MAX;
        }
        return v;
    }

    pub fn clampChunk(c: u32) u32 {
        if (c < CHUNK_MIN) return CHUNK_MIN;
        if (c > CHUNK_MAX) return CHUNK_MAX;
        var v = c;
        if (v & (v - 1) != 0) {
            var p: u32 = CHUNK_MIN;
            while (p < v and p <= CHUNK_MAX) {
                p *= 2;
            }
            v = if (p <= CHUNK_MAX) p else CHUNK_MAX;
        }
        return v;
    }

    pub fn eql(self: CommConfig, other: CommConfig) bool {
        return self.algorithm == other.algorithm and
            self.protocol == other.protocol and
            self.transport == other.transport and
            self.num_channels == other.num_channels and
            self.num_threads == other.num_threads and
            self.chunk_size == other.chunk_size;
    }

    pub fn resourceFootprint(self: CommConfig) f64 {
        return @as(f64, @floatFromInt(self.num_channels)) *
            @as(f64, @floatFromInt(self.num_threads)) *
            @as(f64, @floatFromInt(self.chunk_size));
    }
};

