pub const CommOperator = struct {
    collective_type: CollectiveType,
    data_type: NcclDataType,
    message_size: usize,
    config: CommConfig,
    comm_time: f64,
    done: bool,
    initialized: bool,
    config_history: ArrayList(CommConfig),
    time_history: ArrayList(f64),
    metric_h: f64,
    best_config: CommConfig,
    best_time: f64,

    pub fn init(allocator: Allocator, ctype: CollectiveType, dtype: NcclDataType, msg_size: usize) CommOperator {
        return CommOperator{
            .collective_type = ctype,
            .data_type = dtype,
            .message_size = msg_size,
            .config = CommConfig.initDefault(),
            .comm_time = math.inf(f64),
            .done = false,
            .initialized = false,
            .config_history = ArrayList(CommConfig).init(allocator),
            .time_history = ArrayList(f64).init(allocator),
            .metric_h = math.inf(f64),
            .best_config = CommConfig.initDefault(),
            .best_time = math.inf(f64),
        };
    }

    pub fn deinit(self: *CommOperator) void {
        self.config_history.deinit();
        self.time_history.deinit();
    }

    pub fn updateBest(self: *CommOperator, config: CommConfig, time: f64) void {
        if (time < self.best_time) {
            self.best_time = time;
            self.best_config = config;
        }
    }

    pub fn recordConfig(self: *CommOperator, config: CommConfig, time: f64) !void {
        try self.config_history.append(config);
        try self.time_history.append(time);
        self.updateBest(config, time);
    }
};

