pub const GpuProfiler = struct {
    allocator: Allocator,
    comp_stream: CudaStream,
    comm_stream: CudaStream,
    comp_start: CudaEvent,
    comp_end: CudaEvent,
    comm_start: CudaEvent,
    comm_end: CudaEvent,
    total_start: CudaEvent,
    total_end: CudaEvent,
    device_id: c_int,
    nccl_comm: NcclComm,
    initialized: bool,
    warmup_iters: u32,
    measure_iters: u32,

    pub fn init(allocator: Allocator, device_id: c_int, nccl_comm: NcclComm) !GpuProfiler {
        var profiler = GpuProfiler{
            .allocator = allocator,
            .comp_stream = undefined,
            .comm_stream = undefined,
            .comp_start = undefined,
            .comp_end = undefined,
            .comm_start = undefined,
            .comm_end = undefined,
            .total_start = undefined,
            .total_end = undefined,
            .device_id = device_id,
            .nccl_comm = nccl_comm,
            .initialized = false,
            .warmup_iters = PROFILE_WARMUP_ITERS,
            .measure_iters = PROFILE_MEASURE_ITERS,
        };

        if (cudaSetDevice(device_id) != .success) return error.CudaSetDeviceFailed;
        if (cudaStreamCreate(&profiler.comp_stream) != .success) return error.CudaStreamCreateFailed;
        if (cudaStreamCreate(&profiler.comm_stream) != .success) return error.CudaStreamCreateFailed;
        if (cudaEventCreate(&profiler.comp_start) != .success) return error.CudaEventCreateFailed;
        if (cudaEventCreate(&profiler.comp_end) != .success) return error.CudaEventCreateFailed;
        if (cudaEventCreate(&profiler.comm_start) != .success) return error.CudaEventCreateFailed;
        if (cudaEventCreate(&profiler.comm_end) != .success) return error.CudaEventCreateFailed;
        if (cudaEventCreate(&profiler.total_start) != .success) return error.CudaEventCreateFailed;
        if (cudaEventCreate(&profiler.total_end) != .success) return error.CudaEventCreateFailed;

        profiler.initialized = true;
        return profiler;
    }

    pub fn deinit(self: *GpuProfiler) void {
        if (!self.initialized) return;
        _ = cudaSetDevice(self.device_id);
        _ = cudaEventDestroy(self.total_end);
        _ = cudaEventDestroy(self.total_start);
        _ = cudaEventDestroy(self.comm_end);
        _ = cudaEventDestroy(self.comm_start);
        _ = cudaEventDestroy(self.comp_end);
        _ = cudaEventDestroy(self.comp_start);
        _ = cudaStreamDestroy(self.comm_stream);
        _ = cudaStreamDestroy(self.comp_stream);
        self.initialized = false;
    }

    pub fn applyNcclConfig(config: CommConfig) void {
        const nc_buf: [16]u8 = undefined;
        const nt_buf: [16]u8 = undefined;
        const chunk_buf: [16]u8 = undefined;
        var nc_slice: []u8 = @constCast(nc_buf[0..]);
        var nt_slice: []u8 = @constCast(nt_buf[0..]);
        var chunk_slice: []u8 = @constCast(chunk_buf[0..]);
        const nc_str = std.fmt.bufPrint(nc_slice, "{d}", .{config.num_channels}) catch "8";
        const nt_str = std.fmt.bufPrint(nt_slice, "{d}", .{config.num_threads}) catch "256";
        const chunk_str = std.fmt.bufPrint(chunk_slice, "{d}", .{config.chunk_size}) catch "524288";
        _ = std.posix.setenv(NCCL_ENV_NC, nc_str, 1) catch {};
        _ = std.posix.setenv(NCCL_ENV_NT, nt_str, 1) catch {};
        _ = std.posix.setenv(NCCL_ENV_CHUNK, chunk_str, 1) catch {};
        _ = std.posix.setenv(NCCL_ENV_ALGO, config.algorithm.toString(), 1) catch {};
        _ = std.posix.setenv(NCCL_ENV_PROTO, config.protocol.toString(), 1) catch {};
    }

    pub fn executeCollective(self: *GpuProfiler, comm_op: *const CommOperator, sendbuf: ?*anyopaque, recvbuf: ?*anyopaque) !void {
        switch (comm_op.collective_type) {
            .all_reduce => {
                if (ncclAllReduce(sendbuf, recvbuf, comm_op.message_size / 4, .float32, .sum, self.nccl_comm, self.comm_stream) != .success)
                    return error.NcclAllReduceFailed;
            },
            .all_gather => {
                if (ncclAllGather(sendbuf, recvbuf, comm_op.message_size / 4, .float32, self.nccl_comm, self.comm_stream) != .success)
                    return error.NcclAllGatherFailed;
            },
            .reduce_scatter => {
                var num_ranks: c_int = 1;
                _ = ncclCommCount(self.nccl_comm, &num_ranks);
                const recv_count = comm_op.message_size / (4 * @as(usize, @intCast(num_ranks)));
                if (ncclReduceScatter(sendbuf, recvbuf, recv_count, .float32, .sum, self.nccl_comm, self.comm_stream) != .success)
                    return error.NcclReduceScatterFailed;
            },
            .broadcast => {
                if (ncclBroadcast(sendbuf, recvbuf, comm_op.message_size / 4, .float32, 0, self.nccl_comm, self.comm_stream) != .success)
                    return error.NcclBroadcastFailed;
            },
            .all_to_all => {
                var num_ranks: c_int = 1;
                _ = ncclCommCount(self.nccl_comm, &num_ranks);
                const n = @as(usize, @intCast(num_ranks));
                const chunk = comm_op.message_size / (4 * n);
                var my_rank: c_int = 0;
                _ = ncclCommUserRank(self.nccl_comm, &my_rank);
                if (ncclGroupStart() != .success) return error.NcclGroupStartFailed;
                for (0..n) |peer| {
                    const send_offset = peer * chunk * 4;
                    const recv_offset = peer * chunk * 4;
                    const send_ptr: ?*const anyopaque = if (sendbuf) |sb| @ptrFromInt(@intFromPtr(sb) + send_offset) else null;
                    const recv_ptr: ?*anyopaque = if (recvbuf) |rb| @ptrFromInt(@intFromPtr(rb) + recv_offset) else null;
                    if (ncclSend(send_ptr, chunk, .float32, @intCast(peer), self.nccl_comm, self.comm_stream) != .success)
                        return error.NcclSendFailed;
                    if (ncclRecv(recv_ptr, chunk, .float32, @intCast(peer), self.nccl_comm, self.comm_stream) != .success)
                        return error.NcclRecvFailed;
                }
                if (ncclGroupEnd() != .success) return error.NcclGroupEndFailed;
            },
        }
    }

    pub fn profileOverlap(self: *GpuProfiler, comms: []CommOperator, comp_sendbuf: ?*anyopaque, comm_sendbuf: ?*anyopaque, comm_recvbuf: ?*anyopaque, comp_data_size: usize) !ProfileResult {
        if (!self.initialized) return error.ProfilerNotInitialized;

        if (cudaSetDevice(self.device_id) != .success) return error.CudaSetDeviceFailed;

        for (0..self.warmup_iters) |_| {
            if (comp_sendbuf) |buf| {
                if (cudaMemsetAsync(buf, 0, comp_data_size, self.comp_stream) != .success) return error.CudaMemsetFailed;
            }
            for (comms) |*comm| {
                applyNcclConfig(comm.config);
                try self.executeCollective(comm, comm_sendbuf, comm_recvbuf);
            }
            if (cudaDeviceSynchronize() != .success) return error.CudaSyncFailed;
        }

        var total_comp_ms: f32 = 0.0;
        var total_comm_ms: f32 = 0.0;
        var total_makespan_ms: f32 = 0.0;

        for (0..self.measure_iters) |_| {
            if (cudaEventRecord(self.total_start, self.comp_stream) != .success) return error.CudaEventRecordFailed;
            if (cudaEventRecord(self.comp_start, self.comp_stream) != .success) return error.CudaEventRecordFailed;

            if (comp_sendbuf) |buf| {
                if (cudaMemsetAsync(buf, 0, comp_data_size, self.comp_stream) != .success) return error.CudaMemsetFailed;
            }

            if (cudaEventRecord(self.comp_end, self.comp_stream) != .success) return error.CudaEventRecordFailed;

            if (cudaEventRecord(self.comm_start, self.comm_stream) != .success) return error.CudaEventRecordFailed;

            for (comms) |*comm| {
                applyNcclConfig(comm.config);
                try self.executeCollective(comm, comm_sendbuf, comm_recvbuf);
            }

            if (cudaEventRecord(self.comm_end, self.comm_stream) != .success) return error.CudaEventRecordFailed;
            if (cudaEventRecord(self.total_end, self.comm_stream) != .success) return error.CudaEventRecordFailed;

            if (cudaDeviceSynchronize() != .success) return error.CudaSyncFailed;

            var comp_elapsed: f32 = 0.0;
            var comm_elapsed: f32 = 0.0;
            var total_elapsed: f32 = 0.0;

            if (cudaEventElapsedTime(&comp_elapsed, self.comp_start, self.comp_end) != .success) return error.CudaEventElapsedFailed;
            if (cudaEventElapsedTime(&comm_elapsed, self.comm_start, self.comm_end) != .success) return error.CudaEventElapsedFailed;
            if (cudaEventElapsedTime(&total_elapsed, self.total_start, self.total_end) != .success) return error.CudaEventElapsedFailed;

            total_comp_ms += comp_elapsed;
            total_comm_ms += comm_elapsed;
            total_makespan_ms += total_elapsed;
        }

        const iters_f: f32 = @floatFromInt(self.measure_iters);
        const avg_comp = @as(f64, @floatCast(total_comp_ms / iters_f)) * 1.0e-3;
        const avg_comm = @as(f64, @floatCast(total_comm_ms / iters_f)) * 1.0e-3;
        const avg_makespan = @as(f64, @floatCast(total_makespan_ms / iters_f)) * 1.0e-3;

        return ProfileResult{
            .comp_time = avg_comp,
            .comm_time = avg_comm,
            .total_time = avg_comp + avg_comm,
            .makespan = avg_makespan,
        };
    }
};

pub const ImplSubspace = struct {
    algorithm: Algorithm,
