pub const SubspaceResult = struct {
    subspace: ImplSubspace,
    best_config: CommConfig,
    best_comm_time: f64,
    best_comp_time: f64,
    best_makespan: f64,
};

pub fn generateImplSubspaces(allocator: Allocator) !ArrayList(ImplSubspace) {
    var subspaces = ArrayList(ImplSubspace).init(allocator);
    for (0..Algorithm.count()) |a| {
        for (0..Protocol.count()) |p| {
            for (0..Transport.count()) |t| {
                try subspaces.append(ImplSubspace{
                    .algorithm = Algorithm.fromIndex(a),
                    .protocol = Protocol.fromIndex(p),
                    .transport = Transport.fromIndex(t),
                });
            }
        }
    }
    return subspaces;
}

pub const PriorityMetric = struct {
    pub fn computeH(y_before: f64, y_after: f64, x_before: f64, x_after: f64) f64 {
        const comm_improvement = x_before - x_after;
        if (comm_improvement <= 0.0) return math.inf(f64);
        const comp_overhead = y_after - y_before;
        if (comp_overhead <= 0.0) return -1.0 / comm_improvement;
        return comp_overhead / comm_improvement;
    }

    pub fn computeHMultiComp(y_total_before: f64, y_total_after: f64, x_before: f64, x_after: f64) f64 {
        return computeH(y_total_before, y_total_after, x_before, x_after);
    }

    pub fn isBeneficial(h: f64) bool {
        return h < 1.0 and !math.isInf(h);
    }

    pub fn compare(h_a: f64, h_b: f64) bool {
        if (math.isInf(h_a) and math.isInf(h_b)) return false;
        if (math.isInf(h_a)) return false;
        if (math.isInf(h_b)) return true;
        return h_a < h_b;
    }
};

pub const ResourceEfficientTuner = struct {
    contention_model: *const ContentionModel,
    profiler: *GpuProfiler,
    learning_rate: f64,
    iteration: u32,

    pub fn init(model: *const ContentionModel, profiler: *GpuProfiler) ResourceEfficientTuner {
        return ResourceEfficientTuner{
            .contention_model = model,
            .profiler = profiler,
            .learning_rate = LEARNING_RATE_BASE,
            .iteration = 0,
        };
    }

    pub fn computeLearningRate(self: *ResourceEfficientTuner) void {
        const decay_factor = math.pow(f64, LEARNING_RATE_DECAY, @as(f64, @floatFromInt(self.iteration)));
        self.learning_rate = @max(LEARNING_RATE_BASE * decay_factor, 0.1);
    }

    pub fn computeNCStep(self: *const ResourceEfficientTuner, current_nc: u32) u32 {
        const step_f = @as(f64, @floatFromInt(current_nc)) * self.learning_rate * 0.5;
        const step = @as(u32, @intFromFloat(@max(@ceil(step_f), 1.0)));
        return step;
    }

    pub fn computeNTStep(self: *const ResourceEfficientTuner, current_nt: u32) u32 {
        _ = self;
        if (current_nt < NT_MAX) return current_nt;
        return 0;
    }

    pub fn computeChunkStep(self: *const ResourceEfficientTuner, current_chunk: u32) u32 {
        const step_f = @as(f64, @floatFromInt(current_chunk)) * self.learning_rate * 0.5;
        const step = @as(u32, @intFromFloat(@max(@ceil(step_f), @as(f64, @floatFromInt(CHUNK_MIN)))));
        return step;
    }

    pub fn generateNextConfig(self: *ResourceEfficientTuner, comm: *CommOperator, current_comp_time: f64, current_comm_time: f64) CommConfig {
        if (!comm.initialized) {
            comm.initialized = true;
            var min_config = comm.config;
            min_config.num_channels = NC_MIN;
            min_config.num_threads = NT_MIN;
            min_config.chunk_size = CHUNK_MIN;
            return min_config;
        }

        self.computeLearningRate();
        self.iteration += 1;

        const current = comm.config;

        if (self.shouldTerminate(comm, current_comp_time, current_comm_time)) {
            comm.done = true;
            return comm.best_config;
        }

        var next = current;

        const nc_step = self.computeNCStep(current.num_channels);
        next.num_channels = CommConfig.clampNC(current.num_channels + nc_step);

        const nt_step = self.computeNTStep(current.num_threads);
        if (nt_step > 0) {
            next.num_threads = CommConfig.clampNT(current.num_threads + nt_step);
        }

        const chunk_step = self.computeChunkStep(current.chunk_size);
        next.chunk_size = CommConfig.clampChunk(current.chunk_size + chunk_step);

        return next;
    }

    pub fn shouldTerminate(self: *const ResourceEfficientTuner, comm: *const CommOperator, current_comp_time: f64, current_comm_time: f64) bool {
        _ = self;

        if (comm.time_history.items.len >= 2) {
            const last = comm.time_history.items[comm.time_history.items.len - 1];
            const prev = comm.time_history.items[comm.time_history.items.len - 2];
            if (prev > 0.0) {
                const improvement = (prev - last) / prev;
                if (improvement <= 0.0) return true;
            }
        }

        if (current_comm_time < current_comp_time) {
            if (comm.config.num_channels >= NC_MAX and comm.config.chunk_size >= CHUNK_MAX) {
                return true;
            }
        }

        if (comm.config.num_channels >= NC_MAX and comm.config.num_threads >= NT_MAX and comm.config.chunk_size >= CHUNK_MAX) {
            return true;
        }

        return false;
    }
};

pub const OverlapGroup = struct {
    allocator: Allocator,
    comps: ArrayList(CompOperator),
    comms: ArrayList(CommOperator),
    group_id: u32,
    total_comp_time: f64,
    total_comm_time: f64,
    makespan: f64,
    is_comp_bound: bool,
    optimized: bool,

    pub fn init(allocator: Allocator, group_id: u32) OverlapGroup {
        return OverlapGroup{
            .allocator = allocator,
            .comps = ArrayList(CompOperator).init(allocator),
            .comms = ArrayList(CommOperator).init(allocator),
            .group_id = group_id,
            .total_comp_time = 0.0,
            .total_comm_time = 0.0,
            .makespan = 0.0,
            .is_comp_bound = false,
            .optimized = false,
        };
    }

    pub fn deinit(self: *OverlapGroup) void {
        for (self.comms.items) |*comm| {
            comm.deinit();
        }
        self.comps.deinit();
        self.comms.deinit();
    }

    pub fn addCompOperator(self: *OverlapGroup, comp: CompOperator) !void {
        try self.comps.append(comp);
    }

    pub fn addCommOperator(self: *OverlapGroup, comm: CommOperator) !void {
        try self.comms.append(comm);
    }

    pub fn updateTimings(self: *OverlapGroup, comp_time: f64, comm_time: f64) void {
        self.total_comp_time = comp_time;
        self.total_comm_time = comm_time;
        self.makespan = @max(comp_time, comm_time);
        self.is_comp_bound = comp_time >= comm_time;
    }

    pub fn computeMakespan(self: *const OverlapGroup) f64 {
        return @max(self.total_comp_time, self.total_comm_time);
    }

    pub fn allCommsDone(self: *const OverlapGroup) bool {
        for (self.comms.items) |comm| {
            if (!comm.done) return false;
        }
        return true;
    }

    pub fn findMinHCommIndex(self: *const OverlapGroup) ?usize {
        var min_h: f64 = math.inf(f64);
        var min_idx: ?usize = null;
        for (self.comms.items, 0..) |comm, idx| {
            if (comm.done) continue;
            if (PriorityMetric.compare(comm.metric_h, min_h)) {
                min_h = comm.metric_h;
                min_idx = idx;
            }
        }
        return min_idx;
    }
};

